/* Chat bubble styling overhaul for distinct user and bot appearance */

.chat-bubble-outer {
  display: flex;
  width: 100%;
}

/* User message (right-aligned) */
.chat-bubble-outer-user {
  justify-content: flex-end;
  margin-top: var(--bubble-gap);
  margin-bottom: var(--bubble-gap);
}

/* Bot message (left-aligned) */
.chat-bubble-outer-bot {
  justify-content: flex-start;
  margin-top: var(--bubble-gap);
  margin-bottom: var(--bubble-gap);
}

/* Common chat bubble base */
.chat-bubble {
  max-width: 78vw;
  min-width: 38px;
  word-break: break-word;
  padding: 13px 18px 22px 18px;
  font-size: 1.08rem;
  line-height: 1.52;
  border-radius: var(--bubble-border-radius);
  background: var(--kavia-dark);
  color: var(--text-color);
  box-shadow: 0 2px 12px 0 rgba(30,40,66,0.07);
  margin: 0 0;
  border: 1.5px solid var(--border-color);
  transition: background 0.2s, color 0.2s;
  position: relative;
  outline: none;
   /* space between bubbles (horizontal if side by side, vertical otherwise) */
}

@media (min-width: 480px) {
  .chat-bubble {
    max-width: 58vw;
  }
}

/* USER bubble */
.chat-bubble-user {
  background: var(--primary-color);
  color: #fff;
  border: 1.5px solid var(--primary-color);
  border-bottom-right-radius: 7px;
  border-bottom-left-radius: var(--bubble-border-radius);
  border-top-right-radius: var(--bubble-border-radius);
  border-top-left-radius: var(--bubble-border-radius);
  box-shadow: 0 3px 9px 0 rgba(74,144,226, 0.13);
  text-align: right;
  margin-left: 28vw;
  margin-right: 0;
}

/* BOT bubble */
.chat-bubble-bot {
  background: linear-gradient(110deg, var(--secondary-color) 70%, var(--accent-color) 100%);
  color: #31394d;
  border: 1.5px solid var(--accent-color);
  border-bottom-left-radius: 7px;
  border-bottom-right-radius: var(--bubble-border-radius);
  border-top-left-radius: var(--bubble-border-radius);
  border-top-right-radius: var(--bubble-border-radius);
  box-shadow: 0 3px 10px 0 rgba(255, 209, 102, 0.09);
  text-align: left;
  margin-left: 0;
  margin-right: 28vw;
}

